package extras

import (
	"fmt"
	"strings"
)

// ParsePairs reads "key=value" lines into a map and reports the first malformed line.
func ParsePairs(text string) (map[string]string, error) {
	pairs := map[string]string{}
	for number, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, value, found := strings.Cut(line, "=")
		if !found {
			return nil, fmt.Errorf("line %d: missing '='", number+1)
		}
		pairs[strings.TrimSpace(key)] = strings.TrimSpace(value)
	}
	return pairs, nil
}

package extras

import "math"

// Spread returns the mean and the population standard deviation of samples.
func Spread(samples []float64) (float64, float64) {
	if len(samples) == 0 {
		return 0, 0
	}
	total := 0.0
	for _, s := range samples {
		total += s
	}
	mean := total / float64(len(samples))
	squares := 0.0
	for _, s := range samples {
		squares += (s - mean) * (s - mean)
	}
	deviation := math.Sqrt(squares / float64(len(samples)))
	return mean, deviation
}

package extras

import (
	"regexp"
	"strings"
)

var wordChar = regexp.MustCompile(`[\p{L}\p{N}]`)

// SlugFromInput lower-cases the text and joins its words with single dashes.
func SlugFromInput(input string) string {
	out := ""
	lastDash := true
	for _, ch := range strings.ToLower(strings.TrimSpace(input)) {
		if wordChar.MatchString(string(ch)) {
			out += string(ch)
			lastDash = false
		} else if !lastDash {
			out += "-"
			lastDash = true
		}
	}
	if strings.HasSuffix(out, "-") {
		return out[:len(out)-1]
	}
	return out
}
